  // Privacy modal
  'privacy.title': 'سياسة الخصوصية',
  'privacy.subtitle': 'كيف نحمي ونعالج بياناتك',
  'privacy.lastUpdated': 'آخر تحديث: مارس 2026',
  'privacy.dataCollection.title': 'جمع البيانات',
  'privacy.dataCollection.body': 'نجمع فقط المعلومات اللازمة لخدمة البريد الإلكتروني: اسمك، عنوان بريدك الإلكتروني ومحتوى الرسائل المرسلة والمستلمة. نحن لا نبيع أو نشارك بياناتك الشخصية مع أطراف ثالثة لأغراض التسويق.',
  'privacy.dataUsage.title': 'كيف نستخدم بياناتك',
  'privacy.dataUsage.body': 'تُستخدم بياناتك حصريًا لتشغيل وتحسين خدمة البريد الإلكتروني، بما في ذلك تسليم الرسائل، تصفية البريد العشوائي، ميزات الذكاء الاصطناعي (بموافقتك) وأمان الحساب.',
  'privacy.dataSecurity.title': 'أمان البيانات',
  'privacy.dataSecurity.body': 'نستخدم تشفيرًا قياسيًا في الصناعة (TLS/SSL) لجميع البيانات أثناء النقل وفي حالة السكون. يتم حماية الجلسات باستخدام رموز مشفرة وحماية CSRF. نقوم بمراجعة ممارسات الأمان لدينا بانتظام.',
  'privacy.cookies.title': 'الكوكيز والتخزين المحلي',
  'privacy.cookies.body': 'نستخدم الكوكيز الأساسية والتخزين المحلي للحفاظ على جلستك، وتذكر تفضيلاتك (المظهر، اللغة) وتوفير تجربة سلسة. نحن لا نستخدم كوكيز تتبع من أطراف ثالثة.',
  'privacy.thirdParties.title': 'خدمات الطرف الثالث',
  'privacy.thirdParties.body': 'يمكننا استخدام خدمات الطرف الثالث لوظائف محددة مثل الذكاء الاصطناعي (Anthropic Claude) والإشعارات الفورية. تتبع هذه الخدمات سياساتها الخاصة في الخصوصية وتعالج الحد الأدنى من البيانات اللازمة.',
  'privacy.rights.title': 'حقوقك',
  'privacy.rights.body': 'لديك الحق في الوصول إلى بياناتك الشخصية وتصحيحها وتصديرها أو حذفها في أي وقت. يمكنك إدارة بياناتك في الإعدادات أو الاتصال بدعمنا.',
  'privacy.contact.title': 'اتصل بنا',
  'privacy.contact.body': 'لأسئلة الخصوصية أو طلبات البيانات، اتصل بنا عبر privacy@chatyy.com.br. سنرد في غضون 30 يومًا.',

  // Terms modal
  'terms.title': 'شروط الخدمة',
  'terms.subtitle': 'إرشادات استخدام Chatyy',
  'terms.lastUpdated': 'آخر تحديث: مارس 2026',
  'terms.acceptance.title': 'قبول الشروط',
  'terms.acceptance.body': 'عند الوصول إلى أو استخدام Chatyy، فإنك توافق على شروط الخدمة هذه. إذا كنت لا توافق على أي جزء من هذه الشروط، فلا تستخدم الخدمة.',
  'terms.services.title': 'وصف الخدمات',
  'terms.services.body': 'يوفر Chatyy خدمات الاتصال عبر البريد الإلكتروني بما في ذلك إرسال واستقبال وإدارة الرسائل، بالإضافة إلى ميزات الذكاء الاصطناعي، التكامل مع التقويم ومؤتمرات الفيديو.',
  'terms.accounts.title': 'حسابات المستخدمين',
  'terms.accounts.body': 'أنت مسؤول عن الحفاظ على أمان بيانات اعتمادك. لا تشارك كلمة المرور الخاصة بك ولا تسمح بالوصول غير المصرح به إلى حسابك. يجب أن يكون عمرك 13 عامًا على الأقل لاستخدام هذه الخدمة.',
  'terms.conduct.title': 'الاستخدام المقبول',
  'terms.conduct.body': 'توافق على عدم استخدام الخدمة لإرسال البريد العشوائي، البرمجيات الضارة، التصيد أو أي محتوى غير قانوني. لا تحاول الوصول إلى حسابات مستخدمين آخرين أو تعطيل بنية الخدمة.',
  'terms.content.title': 'ملكية المحتوى',
  'terms.content.body': 'تحتفظ بملكية جميع المحتويات التي تنشئها وترسلها عبر الخدمة. نحن لا نطالب بملكية رسائلك أو مرفقاتك. يمكننا معالجة المحتوى حسب الحاجة لتقديم الخدمة.',
  'terms.limitation.title': 'حدود المسؤولية',
  'terms.limitation.body': 'يتم تقديم Chatyy "كما هو". نسعى لتحقيق 99.9% من التوافر ولكننا لا نضمن خدمة مستمرة. نحن غير مسؤولين عن الأضرار غير المباشرة أو العرضية أو الناتجة عن استخدام الخدمة.',
  'terms.termination.title': 'إنهاء الحساب',
  'terms.termination.body': 'يمكننا تعليق أو إنهاء الحسابات التي تنتهك هذه الشروط. يمكنك حذف حسابك في أي وقت من الإعدادات. بعد الإنهاء، سيتم حذف بياناتك خلال 30 يومًا.',
  'terms.changes.title': 'تغييرات في الشروط',
  'terms.changes.body': 'يمكننا تحديث هذه الشروط بشكل دوري. سنقوم بإخطارك بالتغييرات المهمة عبر البريد الإلكتروني أو إشعار في التطبيق. الاستخدام المستمر بعد التغييرات يعتبر قبولًا للشروط المحدثة.',

